tiles.css:
.t { position: absolute; inset: 0; padding: 8px; display: flex; flex-direction: column; justify-content: space-around; }
b { display: block; font-weight: 300; font-size: 20px; line-height: 1; }
span { font-size: 11px; opacity: .8; }
[data-size='w'] .t, [data-size='l'] .t { flex-direction: row; align-items: center; }
[data-size='s'] span { display: none; } [data-size='s'] b { font-size: 12px; }

.t { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; }
i { width: 45vmin; height: 45vmin; border-radius: 50%; background: #f5f1e0; box-shadow: inset calc((var(--f) * 2 - 1) * 45vmin) 0 0 0 #1f1f3a; }
span { font-size: 11px; opacity: .85; }
[data-size='s'] span { display: none; }

.t { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; }
